data.script:
if (!draft.content.trim()) { context.fail('The draft is empty.'); }
else {
  const title = draft.title, body = draft.processTemplate('[[body]]');
  const url = 'omnifocus:///add?name=' + encodeURIComponent(title) + '&note=' + encodeURIComponent(body);
  if (!app.openURL(url)) context.fail('Could not open OmniFocus.');
}
